{
  "name": "Room Service Process",
  "resources": [
    {
      "name": "Room-service manager",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Sommelier",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Waiter",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Kitchen",
      "capacity": 1,
      "resource_type": "department"
    }
  ],
  "events": [
    {
      "id": "evt_start",
      "name": "Guest calls room service",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_end",
      "name": "Order completed and billed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_take_order",
      "name": "Take down the order",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Room-service manager",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "data_order_ticket"
      ]
    },
    {
      "id": "task_submit_kitchen",
      "name": "Submit order ticket to kitchen",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Room-service manager",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_give_sommelier_order",
      "name": "Give order to sommelier",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Room-service manager",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_assign_waiter",
      "name": "Assign order to waiter",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Room-service manager",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_prep_food",
      "name": "Prepare food",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Kitchen",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_prep_beverages",
      "name": "Fetch wine and prepare alcoholic beverages",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Sommelier",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_prep_cart_and_nonalc",
      "name": "Ready cart and prepare nonalcoholic drinks",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Waiter",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_order_ticket"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_deliver_order",
      "name": "Deliver order to guest's room",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Waiter",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_debit_account",
      "name": "Debit guest's account",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Waiter",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "store_billing_system"
      ]
    }
  ],
  "gateways": [
    {
      "id": "gtw_parallel_split_mgr",
      "name": "Parallel Order Distribution",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gtw_alc_decision",
      "name": "Includes alcoholic beverage?",
      "gateway_type": "exclusive",
      "branch_probabilities": [
        {
          "flow_id": "flow_alc_yes",
          "probability": 0.8
        },
        {
          "flow_id": "flow_alc_no",
          "probability": 0.2
        }
      ],
      "branch_conditions": null
    },
    {
      "id": "gtw_alc_join",
      "name": "Sommelier Branch Join",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gtw_parallel_join_waiter",
      "name": "Preparation Synchronization",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_1",
      "source_id": "evt_start",
      "target_id": "task_take_order",
      "condition_name": null
    },
    {
      "id": "flow_2",
      "source_id": "task_take_order",
      "target_id": "gtw_parallel_split_mgr",
      "condition_name": null
    },
    {
      "id": "flow_mgr_to_kitchen",
      "source_id": "gtw_parallel_split_mgr",
      "target_id": "task_submit_kitchen",
      "condition_name": null
    },
    {
      "id": "flow_mgr_to_alc_dec",
      "source_id": "gtw_parallel_split_mgr",
      "target_id": "gtw_alc_decision",
      "condition_name": null
    },
    {
      "id": "flow_mgr_to_assign_waiter",
      "source_id": "gtw_parallel_split_mgr",
      "target_id": "task_assign_waiter",
      "condition_name": null
    },
    {
      "id": "flow_alc_yes",
      "source_id": "gtw_alc_decision",
      "target_id": "task_give_sommelier_order",
      "condition_name": "Yes (80%)"
    },
    {
      "id": "flow_alc_no",
      "source_id": "gtw_alc_decision",
      "target_id": "gtw_alc_join",
      "condition_name": "No (20%)"
    },
    {
      "id": "flow_sommelier_to_prep",
      "source_id": "task_give_sommelier_order",
      "target_id": "task_prep_beverages",
      "condition_name": null
    },
    {
      "id": "flow_prep_to_alc_join",
      "source_id": "task_prep_beverages",
      "target_id": "gtw_alc_join",
      "condition_name": null
    },
    {
      "id": "flow_kitchen_submit_to_prep",
      "source_id": "task_submit_kitchen",
      "target_id": "task_prep_food",
      "condition_name": null
    },
    {
      "id": "flow_assign_to_prep_cart",
      "source_id": "task_assign_waiter",
      "target_id": "task_prep_cart_and_nonalc",
      "condition_name": null
    },
    {
      "id": "flow_food_to_join",
      "source_id": "task_prep_food",
      "target_id": "gtw_parallel_join_waiter",
      "condition_name": null
    },
    {
      "id": "flow_alc_join_to_par_join",
      "source_id": "gtw_alc_join",
      "target_id": "gtw_parallel_join_waiter",
      "condition_name": null
    },
    {
      "id": "flow_cart_to_join",
      "source_id": "task_prep_cart_and_nonalc",
      "target_id": "gtw_parallel_join_waiter",
      "condition_name": null
    },
    {
      "id": "flow_join_to_deliver",
      "source_id": "gtw_parallel_join_waiter",
      "target_id": "task_deliver_order",
      "condition_name": null
    },
    {
      "id": "flow_deliver_to_debit",
      "source_id": "task_deliver_order",
      "target_id": "task_debit_account",
      "condition_name": null
    },
    {
      "id": "flow_debit_to_end",
      "source_id": "task_debit_account",
      "target_id": "evt_end",
      "condition_name": null
    }
  ],
  "pools": [],
  "message_flows": [],
  "data_objects": [
    {
      "id": "data_order_ticket",
      "name": "Order Ticket"
    }
  ],
  "data_stores": [
    {
      "id": "store_billing_system",
      "name": "Guest Account / Billing System"
    }
  ],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
